-- ═══════════════════════════════════════════════════════════
-- Script khôi phục Users & Roles cho CAMS
-- Database: ObstetricsClinicDB
-- An toàn: dùng MERGE, chỉ INSERT bản ghi còn thiếu
-- Chạy trong SQL Server Management Studio (SSMS)
-- ═══════════════════════════════════════════════════════════

USE [ObstetricsClinicDB]
GO

-- ═══════════════════════════════════════════════════════════
-- Bước 1: Khôi phục Roles (6 vai trò)
-- ═══════════════════════════════════════════════════════════
SET IDENTITY_INSERT [dbo].[roles] ON;
GO

MERGE [dbo].[roles] AS target
USING (VALUES
    (1, N'Admin',    N'Quản trị viên hệ thống — có toàn quyền truy cập và quản lý tất cả chức năng.'),
    (2, N'Doctor',   N'Bác sĩ — khám bệnh, xem và cập nhật bệnh án, kê đơn thuốc, xem kết quả siêu âm.'),
    (3, N'Manager',  N'Quản lý phòng khám — giám sát hoạt động, xem báo cáo, quản lý thanh toán.'),
    (4, N'Staff',    N'Nhân viên lễ tân — đăng ký bệnh nhân, tạo lịch hẹn, xử lý thanh toán và in hóa đơn.'),
    (5, N'Patient',  N'Bệnh nhân — đặt lịch hẹn, xem bệnh án, đơn thuốc và kết quả siêu âm của bản thân.'),
    (6, N'Sonographer', N'Kỹ thuật viên siêu âm — thực hiện siêu âm, tải ảnh và cập nhật kết quả siêu âm.')
) AS source ([id], [role_name], [description])
ON target.[id] = source.[id]
WHEN NOT MATCHED BY TARGET THEN
    INSERT ([id], [role_name], [description])
    VALUES (source.[id], source.[role_name], source.[description]);

SET IDENTITY_INSERT [dbo].[roles] OFF;
GO

-- Kiểm tra roles đã có đủ chưa
SELECT id, role_name FROM [dbo].[roles] ORDER BY id;
GO

-- ═══════════════════════════════════════════════════════════
-- Bước 2: Khôi phục Users (15 tài khoản)
-- ═══════════════════════════════════════════════════════════

-- Kiểm tra số lượng user hiện tại trước khi restore
DECLARE @currentCount INT;
SELECT @currentCount = COUNT(*) FROM [dbo].[users] WHERE is_deleted = 0;
PRINT N'>>> Số user hiện tại (chưa xoá): ' + CAST(@currentCount AS NVARCHAR(10));
GO

SET IDENTITY_INSERT [dbo].[users] ON;
GO

