-- ═══════════════════════════════════════════════════════════
-- Kiểm tra kết quả
-- ═══════════════════════════════════════════════════════════
DECLARE @afterCount INT;
SELECT @afterCount = COUNT(*) FROM [dbo].[users] WHERE is_deleted = 0;
PRINT N'>>> Số user sau khi restore: ' + CAST(@afterCount AS NVARCHAR(10));
GO

-- Liệt kê tất cả user (không giải mã email/phone vì cần passphrase)
SELECT
    u.id,
    u.full_name,
    u.username,
    r.role_name,
    u.status,
    u.is_deleted,
    u.created_at
FROM [dbo].[users] u
LEFT JOIN [dbo].[roles] r ON u.role_id = r.id
ORDER BY u.id;
GO

PRINT N'========================================';
PRINT N'Restore hoàn tất!';
PRINT N'Truy cập: http://localhost:8080/ClinicAppointmentManagementSystem/admin/users/';
PRINT N'========================================';
GO
